	public TraceObjectSchema schemaFromXml(Element schemaElem) {
		SchemaBuilder builder = builder(name(schemaElem.getAttributeValue(ATTR_NAME, "")));

		Map<string, Constructor<object>> ctors = TraceObjectInterfaceUtils.getConstructorsByName();
		foreach (Element ifaceElem in XmlUtilities.getChildren(schemaElem, ELEM_INTERFACE)) {
